const source = $('Execute Workflow Trigger').item.json || {};

const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  message.text ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function parseMoveCommand(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'di chuyen file',
    'chuyen file',
    'move file',
    'dua file'
  ];

  let bodyOriginal = original;
  let bodyNormalized = normalized;

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      bodyOriginal = original.slice(prefix.length + 1).trim();
      bodyNormalized = normalized.slice(prefix.length + 1).trim();
      break;
    }

    if (normalized === prefix) {
      return { fileName: '', targetFolderName: '' };
    }
  }

  const separators = [
    ' vao folder ',
    ' vao thu muc ',
    ' den folder ',
    ' den thu muc ',
    ' to folder ',
    ' into folder ',
    ' to '
  ];

  for (const sep of separators) {
    const index = bodyNormalized.indexOf(sep);

    if (index !== -1) {
      return {
        fileName: cleanName(bodyOriginal.slice(0, index)),
        targetFolderName: cleanName(bodyOriginal.slice(index + sep.length))
      };
    }
  }

  return {
    fileName: cleanName(bodyOriginal),
    targetFolderName: ''
  };
}

const parsed = parseMoveCommand(raw);

const fileId =
  source.fileId ||
  source.targetId ||
  payload.fileId ||
  payload.targetId ||
  '';

const targetFolderId =
  source.targetFolderId ||
  source.folderId ||
  payload.targetFolderId ||
  payload.folderId ||
  '';

const fileName = cleanName(
  source.fileName ||
  payload.fileName ||
  parsed.fileName
);

const targetFolderName = cleanName(
  source.targetFolderName ||
  source.folderName ||
  payload.targetFolderName ||
  payload.folderName ||
  parsed.targetFolderName
);

const hasFileTarget = Boolean(fileId || fileName);
const hasFolderTarget = Boolean(targetFolderId || targetFolderName);

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),

    fileId,
    targetId: fileId,
    fileName,

    targetFolderId,
    folderId: targetFolderId,
    targetFolderName,
    folderName: targetFolderName,

    hasFileTarget,
    hasFolderTarget,
    hasTarget: Boolean(hasFileTarget && hasFolderTarget),

    response: hasFileTarget && hasFolderTarget
      ? ''
      : '📁 <b>Di chuyển file</b>\n\nVí dụ:\n<code>di chuyển file test_n8n.md vào folder test_n8n</code>'
  }
}];

const item = $input.item.json || {};
const fileId = item.fileId || item.targetId || '';

if (!fileId) {
  return [{
    json: {
      ...item,
      response: 'Không có File ID để di chuyển.'
    }
  }];
}

return [{
  json: {
    ...item,
    fileId,
    targetId: fileId
  }
}];

const source = $('Prepare Action').item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      foundFile: false,
      fileId: '',
      targetId: '',
      response: 'Không tìm thấy file phù hợp với: <b>' + escapeHtml(source.fileName || '') + '</b>'
    }
  }];
}

const file = rows[0];

return [{
  json: {
    ...source,
    ...file,
    foundFile: true,
    fileId: file.id || source.fileId || '',
    targetId: file.id || source.targetId || source.fileId || '',
    fileName: file.name || source.fileName || '',
    webViewLink: file.webViewLink || source.webViewLink || '',
    webContentLink: file.webContentLink || source.webContentLink || '',
    mimeType: file.mimeType || source.mimeType || '',
    targetFolderId: source.targetFolderId || '',
    folderId: source.folderId || '',
    targetFolderName: source.targetFolderName || '',
    folderName: source.folderName || ''
  }
}];

const item = $input.item.json || {};
const targetFolderId = item.targetFolderId || item.folderId || '';

if (!targetFolderId) {
  return [{
    json: {
      ...item,
      response: 'Không có Folder ID đích để di chuyển file.'
    }
  }];
}

return [{
  json: {
    ...item,
    targetFolderId,
    folderId: targetFolderId
  }
}];

const source = $input.first().json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

const previous = (() => {
  try { return $('Tim Thay File?').item.json || {}; } catch (e) { return {}; }
})();

if (!rows.length) {
  return [{
    json: {
      ...previous,
      foundFolder: false,
      targetFolderId: '',
      response: 'Không tìm thấy folder đích: <b>' + escapeHtml(previous.targetFolderName || previous.folderName || '') + '</b>'
    }
  }];
}

const folder = rows[0];

return [{
  json: {
    ...previous,
    foundFolder: true,
    targetFolderId: folder.id || previous.targetFolderId || '',
    folderId: folder.id || previous.folderId || '',
    targetFolderName: folder.name || previous.targetFolderName || previous.folderName || '',
    folderName: folder.name || previous.folderName || '',
    targetFolderLink: folder.webViewLink || ''
  }
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

function getJson(nodeName) {
  try { return $(nodeName).item.json || {}; } catch (e) { return {}; }
}

const moveResult = $input.item.json || {};
const prepared = getJson('Prepare Action');
const folderResolved = getJson('Resolve Folder Result');
const folderDirect = getJson('Prepare Folder Target');
const fileResolved = getJson('Resolve File Result');
const fileDirect = getJson('Prepare File Target');

const source = {
  ...prepared,
  ...fileDirect,
  ...fileResolved,
  ...folderDirect,
  ...folderResolved
};

const fileName =
  moveResult.name ||
  source.fileName ||
  source.targetName ||
  'Không rõ tên';

const fileId =
  moveResult.id ||
  source.fileId ||
  source.targetId ||
  '';

const folderName =
  source.targetFolderName ||
  source.folderName ||
  '';

const folderId =
  source.targetFolderId ||
  source.folderId ||
  '';

const link =
  moveResult.webViewLink ||
  source.webViewLink ||
  (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');

const mimeType =
  moveResult.mimeType ||
  source.mimeType ||
  '';

let text = '✅ <b>Đã di chuyển file</b>\n\n';

text += `📄 <b>${escapeHtml(fileName)}</b>\n`;

if (mimeType) {
  text += `Loại: <code>${escapeHtml(mimeType)}</code>\n`;
}

if (fileId) {
  text += `File ID: <code>${escapeHtml(fileId)}</code>\n`;
}

if (folderName || folderId) {
  text += '📁 Folder đích: ';
  if (folderName) text += `<b>${escapeHtml(folderName)}</b>`;
  if (folderId) text += `\nFolder ID: <code>${escapeHtml(folderId)}</code>`;
  text += '\n';
}

if (link) {
  text += `🔗 <a href="${escapeHtml(link)}">Mở file</a>`;
}

return [{
  json: {
    chatId: source.chatId || moveResult.chatId,
    text: text.trim()
  }
}];
